// Build cfg (force Aditya owner like Workflow A)
const cfgRows = $('Read CONFIG').all();
const cfg = {};
for (const it of cfgRows) { const k = it.json.setting; if (k) cfg[String(k).trim()] = it.json.value; }
cfg.OWNER_NAME = 'Aditya'; cfg.SENDER_NAME = 'Aditya';

const OWNER = cfg.OWNER_NAME;
const VALID_OWNERS = Object.keys(cfg).filter((k) => /^OWNER_[A-Z]$/.test(k)).map((k) => String(cfg[k]).trim()).filter((v) => v !== '');
const tz = cfg.TIMEZONE || 'Asia/Kolkata';
const nowTz = DateTime.now().setZone(tz);
const today = nowTz.toISODate();
const todayWeekday = nowTz.toFormat('cccc');
const rotateBySendDay = String(cfg.ROTATE_BY_SEND_DAY || '').trim().toLowerCase() === 'yes';

const startupByName = {};
for (const s of $('Read STARTUPS').all()) { startupByName[String(s.json.startup).trim()] = s.json; }
const investorByName = {};
for (const v of $('Read INVESTORS').all()) { investorByName[String(v.json.investor).trim()] = v.json; }

const blank = (x) => x === undefined || x === null || String(x).trim() === '';
const isYes = (x) => String(x).trim().toLowerCase() === 'yes';
const num = (x) => { const n = parseFloat(String(x).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
const isoRe = /^\d{4}-\d{2}-\d{2}$/;
const parseDue = (x) => { if (blank(x)) return { ok: true, val: null }; const str = String(x).trim(); if (!isoRe.test(str)) return { ok: false, val: null }; const d = DateTime.fromISO(str, { zone: tz }); if (!d.isValid) return { ok: false, val: null }; return { ok: true, val: str }; };
const due = (val) => val !== null && val <= today;

// Synthetic PIPELINE rows: real startup + investor so earlier gates pass.
const future = nowTz.plus({ days: 30 }).toISODate();
const synth = [
  { deal_id: 'SYN-TODAY',  owner: 'Aditya', startup: 'Body & Beyond', investor: '100 Unicorns', email: 'x@example.com', deal_shared: 'No', next_due: today },
  { deal_id: 'SYN-FUTURE', owner: 'Aditya', startup: 'Body & Beyond', investor: '100 Unicorns', email: 'x@example.com', deal_shared: 'No', next_due: future },
  { deal_id: 'SYN-BLANK',  owner: 'Aditya', startup: 'Body & Beyond', investor: '100 Unicorns', email: 'x@example.com', deal_shared: 'No', next_due: '' },
  { deal_id: 'SYN-SHRADHA', owner: 'Shradha', startup: 'Body & Beyond', investor: '100 Unicorns', email: 'x@example.com', deal_shared: 'No', next_due: today },
  { deal_id: 'SYN-BADOWNER', owner: 'Priya', startup: 'Body & Beyond', investor: '100 Unicorns', email: 'x@example.com', deal_shared: 'No', next_due: today },
];

const out = [];
for (const r of synth) {
  const base = { deal_id: r.deal_id, next_due: r.next_due };
  const push = (action, reason, stage) => out.push({ json: Object.assign({}, base, { action, reason, stage: stage || '' }) });

  const ownerVal = String(r.owner || '').trim();
  if (ownerVal === '' || VALID_OWNERS.indexOf(ownerVal) === -1) { push('error', "OWNER_INVALID: owner '" + ownerVal + "' not found in CONFIG", ''); continue; }
  if (ownerVal !== OWNER) { push('skip', 'not-my-owner', ''); continue; }
  if (!blank(r.pause)) { push('skip', 'row-paused', ''); continue; }
  if (!blank(r.investor_response)) { push('skip', 'investor_response-set', ''); continue; }
  if (!blank(r.deal_status) && String(r.deal_status).trim().toLowerCase() !== 'open') { push('skip', 'deal_status-not-open', ''); continue; }
  const inv = investorByName[String(r.investor).trim()];
  if (!inv) { push('error', 'investor-not-found', ''); continue; }
  if (isYes(inv.do_not_contact)) { push('skip', 'do-not-contact', ''); continue; }
  const st = startupByName[String(r.startup).trim()];
  if (!st) { push('error', 'startup-not-found', ''); continue; }
  if (!isYes(st.active)) { push('error', 'startup-not-active', ''); continue; }
  if (blank(r.email)) { push('error', 'email-missing', ''); continue; }
  const varsMissing = blank(st.highlight_1) || blank(st.highlight_2) || blank(st.highlight_3) || blank(st.deck_link) || blank(st.sector) || blank(st.raise_inr_cr) || blank(inv.contact_person) || blank(inv.investor) || blank(st.memo_html);
  if (varsMissing) { push('error', 'template-var-missing', ''); continue; }

  // NEW GATE
  if (!isYes(r.deal_shared)) {
    const pd = parseDue(r.next_due);
    if (!pd.ok) { push('error', 'DATE_PARSE_FAILED', ''); continue; }
    if (!pd.val) { push('error', 'NEXT_DUE_MISSING', ''); continue; }
    if (!due(pd.val)) { push('skip', 'initial-not-due', ''); continue; }
    if (rotateBySendDay && String(st.send_day).trim().toLowerCase() !== todayWeekday.toLowerCase()) { push('skip', 'rotation-not-today', ''); continue; }
    push('send', 'initial', 'INITIAL'); continue;
  }
  push('skip', 'nothing-due', '');
}
return [{ json: { today, future, VALID_OWNERS } }].concat(out);
